# owner: platform
"""Lay students out in seating rows, sorted by last name."""

from typing import List

from rosterkit.models import Student

def _check_inputs(
    students: List[Student], per_row: int
) -> None:
    if per_row <= 0:
        raise ValueError(f"bad seat count: {per_row}")
    if not students:
        raise ValueError("no students to seat")

def _surname_key(student: Student) -> str:
    return student.last_name.casefold()

def _chunk(
    items: List[Student], size: int
) -> List[List[Student]]:
    starts = range(0, len(items), size)
    return [items[start:start + size] for start in starts]

def _row_text(number: int, row: List[Student]) -> str:
    names = " | ".join(seat.display_name for seat in row)
    return f"Row {number}: {names}"

# ---
def seating_rows(
    students: List[Student], per_row: int
) -> List[str]:
    """One text line per row, sorted by last name."""
    _check_inputs(students, per_row)
    ordered = sorted(students, key=_surname_key)
    rows = _chunk(ordered, per_row)
    return [_row_text(i, r) for i, r in enumerate(rows, 1)]

after.tests/test_seating.py:
# owner: platform
import unittest

from rosterkit.models import Student
from rosterkit.seating import seating_rows

def _student(last_name, first_name):
    student_id = f"{last_name}-{first_name}"
    return Student(student_id, last_name, first_name, "A")

class SeatingRowsTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            _student("Halloway", "Juno"),
            _student("Dunmere", "Piet"),
            _student("Varrow", "Ines")
        ]

    def test_row_text(self):
        rows = seating_rows(self.students, 2)
        self.assertEqual(
            rows[0], "Row 1: Dunmere, Piet | Halloway, Juno"
        )

    def test_students_are_sorted_by_last_name(self):
        rows = seating_rows(self.students, 3)
        names = [
            "Dunmere, Piet",
            "Halloway, Juno",
            "Varrow, Ines"
        ]
        expected = "Row 1: " + " | ".join(names)
        self.assertEqual(rows, [expected])

    def test_last_row_may_be_partly_filled(self):
        rows = seating_rows(self.students, 2)
        self.assertEqual(rows[1], "Row 2: Varrow, Ines")
        self.assertEqual(len(rows), 2)

    def test_sort_ignores_case(self):
        students = [
            _student("beck", "Ana"),
            _student("Adams", "Bo")
        ]
        rows = seating_rows(students, 2)
        expected = ["Row 1: Adams, Bo | beck, Ana"]
        self.assertEqual(rows, expected)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -1)

    def test_no_students_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)
